import { describe, expect, it } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO quote -- base premiums", () => {
  it.todo("empty item list -- premium 5 G (processing fee only)");
  it.todo("single sword for a newcomer -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("single amulet for a newcomer -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single staff for a newcomer -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("single potion for a newcomer -- base 40 G + 4 G first insurance + 5 G fee = 49 G");
  it.todo("single rune for a newcomer -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
  it.todo("single moonstone for a newcomer -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G");
});

describe("MHPCO quote -- component blocks", () => {
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block)");
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");
});

describe("MHPCO quote -- item modifiers", () => {
  it.todo("cursed sword adds 50 % of that item's base premium -- 100 G + 50 G curse");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge -- 100 G + 30 G");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge -- base stays 100 G");
  it.todo("cursed sword with enchantment 5 gets both surcharges -- 100 G + 50 G + 30 G");
  it.todo(
    "cursed sword plus plain amulet -- curse surcharge is 50 % of the sword only: 160 G base + 50 G = 210 G before policy modifiers and fee",
  );
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years gets the 20 % loyalty discount");
  it.todo("customer with 1 year gets no loyalty discount");
  it.todo("second quote in a scenario gets the 15 % follow-up contract discount");
  it.todo("first insurance surcharge of 10 % applies to every quote, including follow-up contracts");
});

describe("MHPCO quote -- rounding and integration", () => {
  it.todo("premium of 197.5 G rounds up to 198 G (MHPCO's favor)");
  it.todo("newcomer with a cursed sword -- premium 165 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7 -- premium 160 G");
});

describe("MHPCO quote -- rejections", () => {
  it.todo("quote with an unknown item type (broomstick) -- throws Error");
});

describe("MHPCO claim -- reimbursement clauses", () => {
  it.todo("regular steel sword enchantment 3, damage 500 G -- payout 400 G");
  it.todo("rune damage 200 G -- payout 100 G (no enchantment or material, no special clause)");
  it.todo("dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement)");
  it.todo("steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword enchantment 8, damage 1000 G -- payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (50 % rule wins)");
  it.todo("payout of 350.5 G rounds down to 350 G (MHPCO's favor)");
});

describe("MHPCO claim -- deductible per damage event", () => {
  it.todo("sword (500 G) and amulet (300 G) damaged in one incident -- payout 600 G (deductible per item)");
  it.todo("damage below the deductible yields payout 0 G, not a negative payout");
});

describe("MHPCO claim -- cap", () => {
  it.todo("policy with sword and amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -- cap 2000 G, based on the unmodified insurance value");
  it.todo("policy with a sword and 3 runes -- insurance sum 1750 G, cap 3500 G despite the block discount");
  it.todo("first claim of 1500 G on a sword policy -- payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 G on the same policy -- payout 600 G, remainingCap 0 G");
});

describe("MHPCO claim -- multiple items of the same type", () => {
  it.todo("policy with two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries against two insured swords -- each gets its own deductible");
  it.todo("more sword damage entries than insured swords -- throws Error (whole claim rejected)");
});

describe("MHPCO claim -- rejections", () => {
  it.todo("claim naming an item not covered by the policy (amulet when only a sword is insured) -- throws Error");
  it.todo("claim naming an unknown item type -- throws Error");
  it.todo("claim with a negative damage amount (-200) -- throws Error");
});

describe("MHPCO CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes premium and payout results to stdout");
  it.todo("exits non-zero and writes to stderr, with no results on stdout, when a quote has an unknown item type");
  it.todo("exits non-zero and writes to stderr when a claim is rejected");
});

