export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResults {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
}

function componentGroupBasePremium(type: string, count: number): number {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }

  return count * BASE_PREMIUM_BY_TYPE[type];
}

function basePremium(items: Item[]): number {
  const mainItems = items.filter((item) => !COMPONENT_TYPES.has(item.type));
  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));

  let total = mainItems.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
  for (const [type, count] of countByType(components)) {
    total += componentGroupBasePremium(type, count);
  }

  return total;
}

function itemSurchargeRate(item: Item): number {
  let rate = 0;
  if (item.cursed === true) {
    rate += CURSE_SURCHARGE_RATE;
  }
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
    rate += HIGH_ENCHANTMENT_SURCHARGE_RATE;
  }

  return rate;
}

function itemSurcharges(items: Item[]): number {
  return items.reduce(
    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type] * itemSurchargeRate(item),
    0,
  );
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = basePremium(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return Math.ceil(
    policyBasePremium + itemSurcharges(items) + firstInsuranceSurcharge + PROCESSING_FEE,
  );
}

export function runScenario(scenario: Scenario): ScenarioResults {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium((step as QuoteStep).items) })),
  };
}

