const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

interface Policy {
  items: Item[];
  remainingCap: number;
}

function insuranceValueOf(type: string): number {
  const value = INSURANCE_VALUE_BY_TYPE[type];
  if (value === undefined) {
    throw new Error(`Unknown item type: ${type}`);
  }

  return value;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
}

function damagePayout(damage: Damage): number {
  return Math.max(0, damage.amount - DEDUCTIBLE);
}

function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  const desired = incident.damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
  const payout = Math.floor(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): ScenarioResults {
  const results: StepResult[] = [];
  const policies = new Map<number, Policy>();
  let contracts = 0;

  scenario.steps.forEach((step, index) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy);
      if (policy === undefined) {
        throw new Error(`No policy created by step ${String(step.policy)}`);
      }
      results.push(settleClaim(policy, step.incident));

      return;
    }

    results.push({ premium: quotePremium(step.items, scenario.customer, contracts) });
    policies.set(index, {
      items: step.items,
      remainingCap: insuranceSum(step.items) * CAP_FACTOR,
    });
    contracts += 1;
  });

  return { results };
}

